        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterCEther = address(c).balance;
        assertTrue(!reverted && afterBal == beforeBal - cashOutAmount && afterCEther == beforeCEther - cashOutAmount);
    }

