contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount, uint cashOutAmount) public payable {
        // Fund the test contract so it can deposit Ether into c.
        require(address(this).balance >= depositAmount);

        // Establish a known balance for msg.sender inside c.
        c.Deposit{value: depositAmount}();

        uint beforeBal = c.balances(address(this));
        uint cBefore = address(c).balance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint cAfter = address(c).balance;

        // General rule: the call reverts exactly when the requested amount exceeds the
        // caller's recorded balance; otherwise the caller's recorded balance decreases
        // by exactly the requested amount and c's Ether balance decreases by the same amount.
        assert(
            (cashOutAmount <= beforeBal && !reverted && afterBal == beforeBal - cashOutAmount && cAfter == cBefore - cashOutAmount)
            ||
            (cashOutAmount > beforeBal && reverted && afterBal == beforeBal && cAfter == cBefore)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint cashOutAmount) public payable {
        uint beforeBal = c.balances(address(this));
        require(beforeBal == 0);

        uint cBefore = address(c).balance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint cAfter = address(c).balance;

        assert(
            !reverted &&
            afterBal == 0 &&
            cAfter == cBefore
        );
    }
}

